// Pixel Dünya sunucusu: tek bir ortak dünya, Cloudflare Durable Object üzerinde.
// Oda kodu yok. Siteye giren herkes aynı haritaya bağlanır.
import { DurableObject } from "cloudflare:workers";

// Bu değerler istemcideki (index.html) WORLD_W / WORLD_H ile aynı olmalı.
const W = 2334;
const H = 2583;
const N = W * H;
const H5 = 1230;                 // Dünya 5 (dünya haritası) daha az yüksek: 2334 x 1230
const N5 = W * H5;
const H6 = 983;                  // Dünya 6 (Türkiye haritası): 2334 x 983
const N6 = W * H6;
const NW = { 1: N, 2: N, 3: N, 4: N, 5: N5, 6: N6 };   // dünya başına hücre sayısı
const CHUNK = 65536;      // kayıt parçası: 65536 hücre
// Dünyalar: max = sayaç sınırı (saniye), empty/filled = boş / dolu hücreye piksel koymanın bedeli.
// Sayaç saniyede 1 azalır. Dünya 1'in verisi eski "chunks" tablosunda durur, hiç dokunulmaz.
const WORLDS = {
  1: { max: 60,  empty: 1,   filled: 1, table: "chunks"  },
  2: { max: 120, empty: 0.5, filled: 2, table: "chunks2" },
  3: { max: 900, empty: 2,   filled: 4, table: "chunks3" },
  // Dünya 4: sınırsız piksel. Harita KAYDEDİLİR (chunks4) ama hesabın toplam pikseline SAYILMAZ.
  4: { max: 1,   empty: 0,   filled: 0, table: "chunks4", free: true },
  // Dünya 5: dünya haritası. Sınır 600 sn, boş yer 0,3 sn, dolu yer 1 sn. Kaydedilir (chunks5).
  5: { max: 600, empty: 0.3, filled: 1, table: "chunks5" },
  // Dünya 6: Türkiye haritası. Sınırsız piksel, kaydedilir (chunks6), toplam pikseli artırmaz. Deniz boyanmaz, kırmızı sınırlar dahil kara boyanır.
  6: { max: 1,   empty: 0,   filled: 0, table: "chunks6", free: true },
};
// Deniz maskesi: haritadaki deniz hücreleri (1 = deniz). Denize piksel konamaz.
// Satır satır uzunluk kodlaması: kara, deniz, kara, deniz... (base64 + varint)
const SEA_B64 = "";
function decodeSea(b64, n) {
  let bin = atob(b64), m = new Uint8Array(n), p = 0, i = 0, v = 0;
  while (p < bin.length) {
    let x = 0, sh = 0, c;
    do { c = bin.charCodeAt(p++); x |= (c & 127) << sh; sh += 7; } while (c & 128);
    if (v) m.fill(1, i, i + x);
    i += x; v ^= 1;
  }
  return m;
}
const SEA = decodeSea(SEA_B64, N);
const SEA6_B64 = "";
const SEA6 = decodeSea(SEA6_B64, N6);
const BORD6_B64 = "";     // Dünya 6: il sınırlarının (siyah çizgilerin) hücreleri
const BORD6 = decodeSea(BORD6_B64, N6);
const RED6_B64 = "";     // Dünya 6: kalın kırmızı bölge sınırlarının hücreleri
const RED6 = decodeSea(RED6_B64, N6);
const VERSION = "2026-11-01-kova-yonetici";   // tarayıcıdan sunucu adresini açınca görünür: hangi sürüm yüklü?
// ---- renkler: 1-34 ana palet, 35-63 oyuncuların seçtiği özel renkler ----
const BASE_HEX = ["#ffffff", "#e4e4e4", "#c4c4c4", "#888888", "#4e4e4e", "#000000", "#f4b3af", "#ffa7d1", "#ff54b2", "#ff6565", "#e40001", "#9a0000", "#ffa360", "#e59500", "#d48b58", "#a06b43", "#604029", "#f5dfb0", "#fff788", "#e6d900", "#b5a802", "#94df46", "#01be00", "#688238", "#006512", "#cae4ff", "#00d3de", "#0083c7", "#005683", "#0000ea", "#191973", "#cf6de4", "#c400c4", "#82007f"];
const BLOCKED_C = 26;                 // "Buz mavisi": deniz rengine çok yakın, kimse kullanamaz
const SEA_RGB = [[202, 227, 255], [224, 243, 248]];
const hexRgb = (h) => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
const colDist = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);
const DM_GAP = 1500;        // özel mesaj: kişi başı 1,5 sn
const DM_KEEP = 100;        // her iki kişi arasında saklanan son mesaj sayısı
const CHAT_GAP = 5000;     // sohbet: kişi başı 5 sn'de bir mesaj
const CHAT_KEEP = 200;     // sohbette en fazla bu kadar mesaj saklanır, eskileri silinir
const CHAT_HIST = 100;     // bağlanana en son bu kadar mesaj gönderilir
const FOREVER = 253402300799000;   // süresiz ban/susturma
const trTime = (t) => t >= FOREVER ? "süresiz" : new Date(t + 3 * 3600e3).toISOString().slice(0, 16).replace("T", " ") + " (TSİ)";
const SLACK = 1;          // ağ gecikmesi payı
const FLUSH_MS = 5000;    // harita değişiklikleri en geç 5 sn'de kaydedilir (ücretsiz plan: günlük yazma limiti)
const ACC_FLUSH_MS = 60000; // hesap sayaçları en çok dakikada bir yazılır (herkes çıkınca/durunca hemen)
const MAX_BATCH = 256;    // bir mesajda en fazla piksel

// Mesaj türleri (sunucu -> istemci, Uint32Array'in ilk elemanı)
const T_SNAPSHOT = 1, T_SNAPSHOT_END = 2, T_PIXELS = 3, T_REJECT = 4, T_ONLINE = 5;

// ---- Hesap yardımcıları ----
const enc = new TextEncoder();
const NAME_RE = /^[\p{L}\p{N}_. -]{3,16}$/u;
const hex = (u8) => [...u8].map((b) => b.toString(16).padStart(2, "0")).join("");
const unhex = (h) => Uint8Array.from(h.match(/../g) || [], (x) => parseInt(x, 16));
async function pbkdf2(pw, salt) {
  const key = await crypto.subtle.importKey("raw", enc.encode(pw), "PBKDF2", false, ["deriveBits"]);
  return new Uint8Array(await crypto.subtle.deriveBits(
    { name: "PBKDF2", hash: "SHA-256", salt, iterations: 100000 }, key, 256));
}
function sameBytes(a, b) {
  if (a.length !== b.length) return false;
  let d = 0;
  for (let i = 0; i < a.length; i++) d |= a[i] ^ b[i];
  return d === 0;
}
async function sha256hex(s) {
  return hex(new Uint8Array(await crypto.subtle.digest("SHA-256", enc.encode(s))));
}
class ApiError extends Error {
  constructor(msg, status = 400) { super(msg); this.status = status; }
}
function jsonRes(obj, status = 200) {
  return new Response(JSON.stringify(obj), { status, headers: { "content-type": "application/json; charset=utf-8" } });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const allowedOrigin = (env.ALLOWED_ORIGIN || "").trim();
    if (url.pathname.startsWith("/api/")) {
      const cors = {
        "Access-Control-Allow-Origin": allowedOrigin || "*",
        "Access-Control-Allow-Methods": "POST, OPTIONS",
        "Access-Control-Allow-Headers": "content-type",
        "Access-Control-Max-Age": "86400",
        "Vary": "Origin",
      };
      if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: cors });
      if (allowedOrigin && (request.headers.get("Origin") || "") !== allowedOrigin) {
        return new Response(JSON.stringify({ error: "İzin yok" }), { status: 403, headers: { ...cors, "content-type": "application/json" } });
      }
      const stub = env.WORLD.get(env.WORLD.idFromName("dunya"));
      const res = await stub.fetch(request);
      const headers = new Headers(res.headers);
      for (const [k, v] of Object.entries(cors)) headers.set(k, v);
      return new Response(res.body, { status: res.status, headers });
    }
    if (url.pathname === "/ws") {
      if (request.headers.get("Upgrade") !== "websocket") {
        return new Response("WebSocket gerekli", { status: 426 });
      }
      const allowed = (env.ALLOWED_ORIGIN || "").trim();
      if (allowed) {
        const origin = request.headers.get("Origin") || "";
        if (origin !== allowed) return new Response("İzin yok", { status: 403 });
      }
      const stub = env.WORLD.get(env.WORLD.idFromName("dunya"));
      return stub.fetch(request);
    }
    if (url.pathname === "/durum") {
      const stub = env.WORLD.get(env.WORLD.idFromName("dunya"));
      return stub.fetch(request);
    }
    return new Response("Pixel Dünya sunucusu çalışıyor. Sürüm: " + VERSION, {
      headers: { "content-type": "text/plain; charset=utf-8" },
    });
  },
};

export class World extends DurableObject {
  constructor(ctx, env) {
    super(ctx, env);
    // 0 = boş, 1..12 = renk numarası. Üç ayrı dünya.
    this.worlds = { 1: new Uint8Array(N), 2: new Uint8Array(N), 3: new Uint8Array(N), 4: new Uint8Array(N), 5: new Uint8Array(N5), 6: new Uint8Array(N6) };
    this.dirty = { 1: new Set(), 2: new Set(), 3: new Set(), 4: new Set(), 5: new Set(), 6: new Set() };
    this.rates = new Map();         // oyuncu kimliği -> { used, ts }
    this.accCache = new Map();      // hesap no -> { total }
    this.accDirty = new Set();
    this.throttles = new Map();     // IP sınırları (bellekte)
    for (const w of [1, 2, 3, 4, 5, 6]) {
      if (!WORLDS[w].table) continue;
      this.ctx.storage.sql.exec(
        "CREATE TABLE IF NOT EXISTS " + WORLDS[w].table + " (id INTEGER PRIMARY KEY, data BLOB)"
      );
    }
    this.ctx.storage.sql.exec("CREATE TABLE IF NOT EXISTS settings (k TEXT PRIMARY KEY, v TEXT)");
    this.ctx.storage.sql.exec(
      "CREATE TABLE IF NOT EXISTS chat (id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL, " +
      "name TEXT NOT NULL, acc INTEGER NOT NULL, adm INTEGER NOT NULL DEFAULT 0, text TEXT NOT NULL)"
    );
    // Eski sürümden kalma farklı şemalı sohbet tablosu varsa sohbet sessizce bozulur: sütunlar eksikse yeniden kur
    try {
      const cols = this.rows("PRAGMA table_info(chat)").map((r) => r.name);
      if (!["id", "ts", "name", "acc", "adm", "text"].every((c) => cols.includes(c))) {
        this.ctx.storage.sql.exec("DROP TABLE chat");
        this.ctx.storage.sql.exec(
          "CREATE TABLE chat (id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL, " +
          "name TEXT NOT NULL, acc INTEGER NOT NULL, adm INTEGER NOT NULL DEFAULT 0, text TEXT NOT NULL)"
        );
      }
    } catch (e) {}
    this.dmLast = new Map(); this.colLast = new Map(); this.lblLast = new Map();
    this.ctx.storage.sql.exec("CREATE TABLE IF NOT EXISTS labels (id INTEGER PRIMARY KEY AUTOINCREMENT, w INTEGER NOT NULL, acc INTEGER NOT NULL, aname TEXT NOT NULL, name TEXT NOT NULL, x INTEGER NOT NULL, y INTEGER NOT NULL, bw INTEGER NOT NULL, bh INTEGER NOT NULL, c INTEGER NOT NULL, ts INTEGER NOT NULL)");
    this.ctx.storage.sql.exec("CREATE TABLE IF NOT EXISTS ccolors (slot INTEGER PRIMARY KEY, hex TEXT NOT NULL)");
    this.ccolors = new Map();
    try { for (const r of this.rows("SELECT slot, hex FROM ccolors")) this.ccolors.set(r.slot, r.hex); } catch (e) {}
    this.chatLast = new Map();      // hesap -> son mesaj zamanı
    this.lastPixelAt = 0; this.lastAccFlush = 0;
    this.chatMem = []; this.chatSeq = 0;      // son mesajlar bellekte de tutulur: veritabanı yazması hata verse de sohbet çalışır
    const seaRow = [...this.ctx.storage.sql.exec("SELECT v FROM settings WHERE k = 'sea'")][0];
    this.sea = seaRow ? seaRow.v !== "0" : true;   // deniz koruması: varsayılan AÇIK
    const b6Row = [...this.ctx.storage.sql.exec("SELECT v FROM settings WHERE k = 'b6p'")][0];
    this.b6p = b6Row ? b6Row.v !== "0" : true;
    const r6Row = [...this.ctx.storage.sql.exec("SELECT v FROM settings WHERE k = 'r6p'")][0];
    this.r6p = r6Row ? r6Row.v !== "0" : true;     // Dünya 6: kırmızı bölge sınırları boyanabilir     // Dünya 6: siyah il sınırları boyanabilir (varsayılan AÇIK = şimdiki hali)
    this.ctx.storage.sql.exec(
      "CREATE TABLE IF NOT EXISTS acc_rates (acc INTEGER NOT NULL, w INTEGER NOT NULL, " +
      "used REAL NOT NULL DEFAULT 0, ts INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (acc, w))"
    );
    this.ctx.storage.sql.exec(
      "CREATE TABLE IF NOT EXISTS accounts (" +
      "id INTEGER PRIMARY KEY, name TEXT NOT NULL, name_lc TEXT NOT NULL UNIQUE, " +
      "salt TEXT NOT NULL, hash TEXT NOT NULL, total INTEGER NOT NULL DEFAULT 0, " +
      "used REAL NOT NULL DEFAULT 0, ts INTEGER NOT NULL DEFAULT 0, " +
      "fails INTEGER NOT NULL DEFAULT 0, lock_until INTEGER NOT NULL DEFAULT 0)"
    );
    try {   // eski veritabanlarında profil sütunu yoksa ekle
      const acols = this.rows("PRAGMA table_info(accounts)").map((r) => r.name);
      if (!acols.includes("avatar")) this.ctx.storage.sql.exec("ALTER TABLE accounts ADD COLUMN avatar TEXT NOT NULL DEFAULT ''");
      if (!acols.includes("msgs")) {
        this.ctx.storage.sql.exec("ALTER TABLE accounts ADD COLUMN msgs INTEGER NOT NULL DEFAULT 0");
        try { this.ctx.storage.sql.exec("UPDATE accounts SET msgs = (SELECT COUNT(*) FROM chat WHERE chat.acc = accounts.id)"); } catch (e) {}   // eskiden yazılanlar sayılsın
      }
      if (!acols.includes("ban_until")) this.ctx.storage.sql.exec("ALTER TABLE accounts ADD COLUMN ban_until INTEGER NOT NULL DEFAULT 0");
      if (!acols.includes("mute_until")) this.ctx.storage.sql.exec("ALTER TABLE accounts ADD COLUMN mute_until INTEGER NOT NULL DEFAULT 0");
    } catch (e) {}
    this.ctx.storage.sql.exec("CREATE TABLE IF NOT EXISTS dms (id INTEGER PRIMARY KEY AUTOINCREMENT, a INTEGER NOT NULL, b INTEGER NOT NULL, frm INTEGER NOT NULL, ts INTEGER NOT NULL, text TEXT NOT NULL)");
    this.ctx.storage.sql.exec("CREATE INDEX IF NOT EXISTS dms_ab ON dms (a, b, id)");
    this.ctx.storage.sql.exec(
      "CREATE TABLE IF NOT EXISTS sessions (hash TEXT PRIMARY KEY, acc INTEGER NOT NULL)"
    );
    this.ctx.storage.sql.exec("CREATE TABLE IF NOT EXISTS admin_sessions (hash TEXT PRIMARY KEY)");
    this.ctx.setWebSocketAutoResponse(new WebSocketRequestResponsePair("ping", "pong"));
    this.ctx.blockConcurrencyWhile(async () => {
      for (const w of [1, 2, 3, 4, 5, 6]) {
        if (!WORLDS[w].table) continue;
        for (const row of this.ctx.storage.sql.exec("SELECT id, data FROM " + WORLDS[w].table)) {
          const start = row.id * CHUNK;
          if (start >= NW[w]) continue;
          const arr = new Uint8Array(row.data);
          this.worlds[w].set(arr.subarray(0, Math.min(arr.length, NW[w] - start)), start);
        }
      }
    });
  }

  // ---------- Hesap API ----------
  rows(q, ...args) { return [...this.ctx.storage.sql.exec(q, ...args)]; }

  tooMany(key, max) {
    const t = this.throttles.get(key);
    return !!t && Date.now() < t.until && t.n >= max;
  }
  hit(key, windowMs) {
    const now = Date.now();
    let t = this.throttles.get(key);
    if (!t || now >= t.until) t = { n: 0, until: now + windowMs };
    t.n++;
    this.throttles.set(key, t);
    if (this.throttles.size > 5000) {
      for (const [k, v] of this.throttles) if (now >= v.until) this.throttles.delete(k);
    }
  }

  async newSession(accId) {
    const raw = hex(crypto.getRandomValues(new Uint8Array(32)));
    this.ctx.storage.sql.exec("INSERT INTO sessions (hash, acc) VALUES (?, ?)", await sha256hex(raw), accId);
    return raw;
  }

  async accountByToken(token) {
    if (!token || token.length !== 64) return null;
    const r = this.rows(
      "SELECT a.* FROM sessions s JOIN accounts a ON a.id = s.acc WHERE s.hash = ?",
      await sha256hex(token)
    );
    return r[0] || null;
  }

  accountView(row) {
    return { id: row.id, name: row.name, total: row.total, used: row.used, avatar: row.avatar || "", msgs: row.msgs || 0 };
  }

  cleanName(v) {
    const name = String(v || "").trim().replace(/\s+/g, " ");
    if (!NAME_RE.test(name)) throw new ApiError("Ad 3-16 karakter olmalı (harf, rakam, boşluk, _ . -)");
    return name;
  }
  cleanPass(v) {
    const pw = String(v || "");
    if (pw.length < 6) throw new ApiError("Şifre en az 6 karakter olmalı");
    if (pw.length > 64) throw new ApiError("Şifre en fazla 64 karakter olabilir");
    return pw;
  }

  async register(body, ip) {
    if (this.tooMany("reg:" + ip, 5)) throw new ApiError("Çok fazla hesap açıldı, daha sonra tekrar dene", 429);
    const name = this.cleanName(body.name);
    const pw = this.cleanPass(body.password);
    if (this.rows("SELECT 1 FROM accounts WHERE name_lc = ?", name.toLowerCase()).length) {
      throw new ApiError("Bu ad alınmış", 409);
    }
    this.hit("reg:" + ip, 3600 * 1000);
    let id = 0;
    for (let i = 0; i < 50; i++) {
      const n = 100000 + (crypto.getRandomValues(new Uint32Array(1))[0] % 900000);
      if (!this.rows("SELECT 1 FROM accounts WHERE id = ?", n).length) { id = n; break; }
    }
    if (!id) throw new ApiError("ID üretilemedi, tekrar dene", 503);
    const salt = crypto.getRandomValues(new Uint8Array(16));
    const hash = await pbkdf2(pw, salt);
    this.ctx.storage.sql.exec(
      "INSERT INTO accounts (id, name, name_lc, salt, hash) VALUES (?, ?, ?, ?, ?)",
      id, name, name.toLowerCase(), hex(salt), hex(hash)
    );
    const token = await this.newSession(id);
    return { token, account: { id, name, total: 0, used: 0 } };
  }

  async login(body, ip) {
    if (this.tooMany("login:" + ip, 10)) throw new ApiError("Çok fazla hatalı deneme, biraz bekle", 429);
    const name = String(body.name || "").trim().replace(/\s+/g, " ");
    const pw = String(body.password || "").slice(0, 64);
    const row = this.rows("SELECT * FROM accounts WHERE name_lc = ?", name.toLowerCase())[0];
    const now = Date.now();
    if (row && row.lock_until > now) throw new ApiError("Bu hesap kısa süreliğine kilitlendi, birkaç dakika sonra dene", 429);
    const calc = await pbkdf2(pw, row ? unhex(row.salt) : new Uint8Array(16));
    if (!row || !sameBytes(calc, unhex(row.hash))) {
      this.hit("login:" + ip, 15 * 60 * 1000);
      if (row) {
        const fails = row.fails + 1;
        this.ctx.storage.sql.exec(
          "UPDATE accounts SET fails = ?, lock_until = ? WHERE id = ?",
          fails >= 5 ? 0 : fails, fails >= 5 ? now + 5 * 60 * 1000 : 0, row.id
        );
      }
      throw new ApiError("Ad veya şifre yanlış", 401);
    }
    this.ctx.storage.sql.exec("UPDATE accounts SET fails = 0, lock_until = 0 WHERE id = ?", row.id);
    if (row.ban_until > now) throw new ApiError("Hesabın yasaklandı. Süre: " + trTime(row.ban_until), 403);
    const token = await this.newSession(row.id);
    return { token, account: this.accountView(this.accountFresh(row)) };
  }

  async recover(body, ip) {
    if (this.tooMany("rec:" + ip, 8)) throw new ApiError("Çok fazla hatalı deneme, daha sonra tekrar dene", 429);
    const idStr = String(body.id || "").trim();
    const pw = this.cleanPass(body.password);
    const row = /^\d{6}$/.test(idStr) ? this.rows("SELECT * FROM accounts WHERE id = ?", Number(idStr))[0] : null;
    if (!row) {
      this.hit("rec:" + ip, 3600 * 1000);
      throw new ApiError("Bu ID ile hesap bulunamadı", 404);
    }
    const salt = crypto.getRandomValues(new Uint8Array(16));
    const hash = await pbkdf2(pw, salt);
    this.ctx.storage.sql.exec(
      "UPDATE accounts SET salt = ?, hash = ?, fails = 0, lock_until = 0 WHERE id = ?",
      hex(salt), hex(hash), row.id
    );
    this.ctx.storage.sql.exec("DELETE FROM sessions WHERE acc = ?", row.id); // eski oturumlar kapanır
    const token = await this.newSession(row.id);
    return { token, account: this.accountView(this.accountFresh(row)) };
  }

  async logout(body) {
    const token = String(body.token || "");
    if (token.length === 64) this.ctx.storage.sql.exec("DELETE FROM sessions WHERE hash = ?", await sha256hex(token));
    return { ok: true };
  }

  // Hesabın bir dünyadaki sayacı. Dünya 1 eski "accounts" satırında, 2 ve 3 acc_rates içinde.
  loadAccRate(accId, w) {
    if (w === 1) {
      const r = this.rows("SELECT used, ts FROM accounts WHERE id = ?", accId)[0];
      return r ? { used: r.used, ts: r.ts } : { used: 0, ts: 0 };
    }
    const r = this.rows("SELECT used, ts FROM acc_rates WHERE acc = ? AND w = ?", accId, w)[0];
    return r ? { used: r.used, ts: r.ts } : { used: 0, ts: 0 };
  }

  // Bellekte daha yeni sayaç varsa onu kullan
  accountFresh(row) {
    const c = this.accCache.get(row.id);
    if (!c) return row;
    return { ...row, total: c.total };
  }

  // ---------- Yönetici ----------
  // Kod koda yazılmaz: Cloudflare'da ADMIN_CODE adlı gizli değer (secret) olarak tutulur.
  async adminLogin(body, ip) {
    const secret = String((this.env && this.env.ADMIN_CODE) || "");
    if (!secret) throw new ApiError("Yönetici özelliği kapalı", 503);
    if (this.tooMany("adm:" + ip, 5) || this.tooMany("adm:all", 20)) {
      throw new ApiError("Çok fazla hatalı deneme, daha sonra tekrar dene", 429);
    }
    const given = await sha256hex(String(body.code || "").slice(0, 200));
    const want = await sha256hex(secret);
    if (!sameBytes(unhex(given), unhex(want))) {
      this.hit("adm:" + ip, 3600 * 1000);
      this.hit("adm:all", 3600 * 1000);
      throw new ApiError("Yönetici kodu yanlış", 401);
    }
    const raw = hex(crypto.getRandomValues(new Uint8Array(32)));
    this.ctx.storage.sql.exec("INSERT INTO admin_sessions (hash) VALUES (?)", await sha256hex(raw));
    return { token: raw };
  }

  async adminLogout(body) {
    const t = String(body.token || "");
    if (t.length !== 64) return { ok: true };
    const h = await sha256hex(t);
    this.ctx.storage.sql.exec("DELETE FROM admin_sessions WHERE hash = ?", h);
    for (const s of this.ctx.getWebSockets()) {          // açık bağlantılarda da yetkiyi kaldır
      const a = s.deserializeAttachment() || {};
      if (a.ah === h) s.serializeAttachment({ ...a, admin: false, unl: false });
    }
    return { ok: true };
  }

  // ---------- Sohbet ----------
  chatHistory() {
    try {
      return this.rows("SELECT id, ts, name, acc, adm, text FROM chat ORDER BY id DESC LIMIT " + CHAT_HIST)
        .reverse().map((r) => ({ id: r.id, ts: r.ts, name: r.name, acc: r.acc, adm: r.adm === 1, text: r.text }));
    } catch (e) { return this.chatMem.slice(); }
  }

  avatarOf(acc) {
    try { const r = this.rows("SELECT avatar FROM accounts WHERE id = ?", acc)[0]; return (r && r.avatar) || ""; } catch (e) { return ""; }
  }

  // Sohbet geçmişindeki hesapların profilleri (her hesap bir kez gönderilir)
  chatAvatars(msgs) {
    const out = {};
    for (const acc of new Set(msgs.map((m) => m.acc).filter(Boolean))) {
      const av = this.avatarOf(acc);
      if (av) out[acc] = av;
    }
    return out;
  }

  async setAvatar(body) {
    const acc = await this.accountByToken(String(body.token || ""));
    if (!acc) throw new ApiError("Giriş yapman gerekiyor", 401);
    if (this.tooMany("av:" + acc.id, 10)) throw new ApiError("Çok sık değiştiriyorsun, biraz bekle", 429);
    this.hit("av:" + acc.id, 60000);
    const av = String(body.avatar || "");
    const okColor = /^c([0-9]|[12][0-9]|3[0-3])$/.test(av);
    const okPhoto = av.length <= 16000 && /^data:image\/jpeg;base64,\/9j\/[A-Za-z0-9+\/=]+$/.test(av);
    if (av !== "" && !okColor && !okPhoto) throw new ApiError("Geçersiz profil", 400);
    this.ctx.storage.sql.exec("UPDATE accounts SET avatar = ? WHERE id = ?", av, acc.id);
    this.broadcastJson({ type: "avatar", acc: acc.id, av });
    return { ok: true, avatar: av };
  }

  broadcastJson(obj) {
    const msg = JSON.stringify(obj);
    for (const s of this.ctx.getWebSockets()) { try { s.send(msg); } catch (e) { /* kapanmış bağlantı */ } }
  }

  // ---- ülke isimleri (kova ile seçilen bölgelere verilen büyük yazılar) ----
  labelList(w) {
    try { return this.rows("SELECT id, acc, aname AS an, name, x, y, bw, bh, c FROM labels WHERE w = ? ORDER BY id", w); } catch (e) { return []; }
  }
  toWorld(w, obj) {
    const msg = JSON.stringify(obj);
    for (const x of this.ctx.getWebSockets()) {
      const t = x.deserializeAttachment() || {};
      if ((WORLDS[t.w] ? t.w : 1) === w) { try { x.send(msg); } catch (e) {} }
    }
  }
  handleLabel(ws, a, m) {
    const err = (msg) => { try { ws.send(JSON.stringify({ type: "labelerr", msg })); } catch (e) {} };
    if (!a.admin) return err("Ülke ismi vermek sadece yöneticilere açık");
    const clean = (v) => String(v || "").replace(/[\u0000-\u001f\u007f]/g, " ").replace(/\s+/g, " ").trim().slice(0, 24);
    const now = Date.now();
    if (m.type === "labelset") {
      const w = WORLDS[a.w] ? a.w : 1;
      const IHs = NW[w] / W;
      const x = Number(m.x), y = Number(m.y), bw = Number(m.bw), bh = Number(m.bh), c = Number(m.c);
      if (![x, y, bw, bh, c].every(Number.isInteger)) return err("Geçersiz istek");
      if (x < 0 || y < 0 || x >= W || y >= IHs || bw < 1 || bh < 1 || bw > W || bh > IHs || c < 1 || c > 63) return err("Geçersiz konum");
      const name = clean(m.name);
      if (!name) return err("Bir isim yaz");
      if (this.worlds[w][y * W + x] !== c) return err("Bölgenin rengi değişmiş, tekrar dene");
      try {
        const mu = a.acc ? this.rows("SELECT mute_until FROM accounts WHERE id = ?", a.acc)[0] : null;
        if (mu && mu.mute_until > now) return err("Susturuldun. Süre: " + trTime(mu.mute_until));
      } catch (e) {}
      const key = a.acc || "adm";
      if ((this.lblLast.get(key) || 0) > now - 3000) return err("Biraz bekle");
      if (a.acc && !a.admin && this.rows("SELECT COUNT(*) AS n FROM labels WHERE acc = ? AND w = ?", a.acc, w)[0].n >= 6) return err("Bu dünyada en fazla 6 isim verebilirsin. Ayarlardan birini sil.");
      this.lblLast.set(key, now); if (this.lblLast.size > 2000) this.lblLast.clear();
      this.ctx.storage.sql.exec("INSERT INTO labels (w, acc, aname, name, x, y, bw, bh, c, ts) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        w, a.acc || 0, a.name || "yönetici", name, x, y, bw, bh, c, now);
      const id = this.rows("SELECT MAX(id) AS id FROM labels")[0].id;
      this.toWorld(w, { type: "label", label: { id, acc: a.acc || 0, an: a.name || "yönetici", name, x, y, bw, bh, c } });
      return;
    }
    const id = Number(m.id);
    if (!Number.isInteger(id)) return;
    const row = this.rows("SELECT id, w, acc FROM labels WHERE id = ?", id)[0];
    if (!row) return;
    if (!a.admin && row.acc !== a.acc) return err("Bu ismi sadece veren kişi değiştirebilir");
    if (m.type === "labelren") {
      const name = clean(m.name); if (!name) return err("Bir isim yaz");
      this.ctx.storage.sql.exec("UPDATE labels SET name = ? WHERE id = ?", name, id);
      this.toWorld(row.w, { type: "labelren", id, name });
    } else {
      this.ctx.storage.sql.exec("DELETE FROM labels WHERE id = ?", id);
      this.toWorld(row.w, { type: "labeldel", id });
    }
  }

  // ---- özel renk ----
  handleNewColor(ws, a, m) {
    const send = (o) => { try { ws.send(JSON.stringify(o)); } catch (e) {} };
    const err = (msg) => send({ type: "colorerr", msg });
    if (!a.acc && !a.admin) return err("Özel renk seçmek için hesap aç");
    const hex = String(m.hex || "").toLowerCase();
    if (!/^#[0-9a-f]{6}$/.test(hex)) return err("Geçersiz renk");
    const rgb = hexRgb(hex);
    for (const sc of SEA_RGB) if (colDist(rgb, sc) < 24) return err("Bu renk deniz rengine çok yakın, kullanılamaz");
    const all = [];
    BASE_HEX.forEach((h, i) => { if (i + 1 !== BLOCKED_C) all.push([i + 1, h]); });
    for (const [sl, h] of this.ccolors) all.push([sl, h]);
    let best = 1, bd = 1e9;
    for (const [sl, h] of all) { const d = colDist(rgb, hexRgb(h)); if (d < bd) { bd = d; best = sl; } }
    const hexOf = (sl) => (sl <= 34 ? BASE_HEX[sl - 1] : this.ccolors.get(sl));
    if (bd <= 10) return send({ type: "mycolor", slot: best, hex: hexOf(best) });     // zaten var (ya da neredeyse aynısı)
    const now = Date.now(), key = a.acc || "adm";
    if ((this.colLast.get(key) || 0) > now - 15000) return err("Yeni renk için biraz bekle");
    let slot = 0;
    for (let sl = 35; sl <= 63; sl++) if (!this.ccolors.has(sl)) { slot = sl; break; }
    if (!slot) return send({ type: "mycolor", slot: best, hex: hexOf(best), full: true });   // yer kalmadı: en yakın renk
    this.colLast.set(key, now);
    if (this.colLast.size > 2000) this.colLast.clear();
    this.ctx.storage.sql.exec("INSERT INTO ccolors (slot, hex) VALUES (?, ?)", slot, hex);
    this.ccolors.set(slot, hex);
    this.broadcastJson({ type: "color", slot, hex });
    send({ type: "mycolor", slot, hex });
  }

  // ---- özel mesaj (DM) ----
  handleDm(ws, a, m) {
    const err = (msg) => { try { ws.send(JSON.stringify({ type: "dmerr", msg })); } catch (e) {} };
    if (!a.acc) return err("DM için hesap aç");
    const to = Number(m.to);
    if (!Number.isInteger(to) || to <= 0 || to === a.acc) return err("Geçersiz kişi");
    const now = Date.now();
    try {
      const mu = this.rows("SELECT mute_until FROM accounts WHERE id = ?", a.acc)[0];
      if (mu && mu.mute_until > now) return err("Susturuldun. Süre: " + trTime(mu.mute_until));
    } catch (e) {}
    const peer = this.rows("SELECT id, name FROM accounts WHERE id = ?", to)[0];
    if (!peer) return err("Kişi bulunamadı");
    const wait = DM_GAP - (now - (this.dmLast.get(a.acc) || 0));
    if (wait > 0) return err("Çok hızlı yazıyorsun, " + Math.ceil(wait / 1000) + " sn bekle");
    const text = String(m.text || "").replace(/[\u0000-\u001f\u007f]/g, " ").replace(/\s+/g, " ").trim().slice(0, 200);
    if (!text) return;
    this.dmLast.set(a.acc, now);
    if (this.dmLast.size > 2000) this.dmLast.clear();
    const lo = Math.min(a.acc, to), hi = Math.max(a.acc, to);
    let id = 0;
    try {
      this.ctx.storage.sql.exec("INSERT INTO dms (a, b, frm, ts, text) VALUES (?, ?, ?, ?, ?)", lo, hi, a.acc, now, text);
      id = this.rows("SELECT MAX(id) AS id FROM dms")[0].id;
      if (id % 25 === 0) this.ctx.storage.sql.exec(
        "DELETE FROM dms WHERE a = ? AND b = ? AND id NOT IN (SELECT id FROM dms WHERE a = ? AND b = ? ORDER BY id DESC LIMIT " + DM_KEEP + ")", lo, hi, lo, hi);
    } catch (e) { return err("Mesaj kaydedilemedi"); }
    const out = JSON.stringify({ type: "dm", id, ts: now, from: a.acc, fromName: a.name || "?", to, toName: peer.name, text });
    for (const x of this.ctx.getWebSockets()) {          // gönderenin ve alıcının tüm bağlantılarına
      const t = x.deserializeAttachment() || {};
      if (t.acc === a.acc || t.acc === to) { try { x.send(out); } catch (e) {} }
    }
  }

  dmHist(ws, a, m) {
    if (!a.acc) return;
    const to = Number(m.with);
    if (!Number.isInteger(to) || to <= 0) return;
    const lo = Math.min(a.acc, to), hi = Math.max(a.acc, to);
    const peer = this.rows("SELECT name FROM accounts WHERE id = ?", to)[0];
    const msgs = this.rows("SELECT id, ts, frm, text FROM dms WHERE a = ? AND b = ? ORDER BY id DESC LIMIT 50", lo, hi)
      .reverse().map((r) => ({ id: r.id, ts: r.ts, from: r.frm, text: r.text }));
    const names = {}; names[a.acc] = a.name || "?"; names[to] = peer ? peer.name : "?";
    ws.send(JSON.stringify({ type: "dmhist", with: to, names, msgs }));
  }

  dmList(ws, a) {
    if (!a.acc) return;
    const rows = this.rows(
      "SELECT CASE WHEN a = ? THEN b ELSE a END AS peer, MAX(id) AS last FROM dms WHERE a = ? OR b = ? GROUP BY peer ORDER BY last DESC LIMIT 12",
      a.acc, a.acc, a.acc);
    const list = [];
    for (const r of rows) {
      const p = this.rows("SELECT name FROM accounts WHERE id = ?", r.peer)[0];
      if (p) list.push({ id: r.peer, name: p.name });
    }
    ws.send(JSON.stringify({ type: "dmlist", list }));
  }

  handleChat(ws, a, m) {
    if (!a.acc) { ws.send(JSON.stringify({ type: "chaterr", msg: "Yazmak için hesap aç" })); return; }
    const now = Date.now();
    try {
      const mu = this.rows("SELECT mute_until FROM accounts WHERE id = ?", a.acc)[0];
      if (mu && mu.mute_until > now) { ws.send(JSON.stringify({ type: "chaterr", msg: "Susturuldun. Süre: " + trTime(mu.mute_until) })); return; }
    } catch (e) {}
    const wait = CHAT_GAP - (now - (this.chatLast.get(a.acc) || 0));
    if (wait > 0) {
      ws.send(JSON.stringify({ type: "chaterr", msg: "Çok hızlı yazıyorsun, " + Math.ceil(wait / 1000) + " sn bekle" })); return;
    }
    const text = String(m.text || "").replace(/[\u0000-\u001f\u007f]/g, " ").replace(/\s+/g, " ").trim().slice(0, 200);
    if (!text) return;
    this.chatLast.set(a.acc, now);
    if (this.chatLast.size > 2000) this.chatLast.clear();
    const adm = a.admin ? 1 : 0;
    let id = 0;
    try {
      this.ctx.storage.sql.exec("INSERT INTO chat (ts, name, acc, adm, text) VALUES (?, ?, ?, ?, ?)", now, a.name || "?", a.acc, adm, text);
      id = this.rows("SELECT MAX(id) AS id FROM chat")[0].id;
      if (id % 20 === 0) this.ctx.storage.sql.exec("DELETE FROM chat WHERE id <= ?", id - CHAT_KEEP);   // eski mesajlar silinir (yazma sayısı az olsun diye 20'de bir)
    } catch (e) { id = 0; }                                                       // kaydedilemese de mesaj herkese gider
    if (!id) id = this.chatSeq = Math.max(this.chatSeq + 1, Date.now());
    const name = a.name || "?";
    let msgN = 0;
    try {
      this.ctx.storage.sql.exec("UPDATE accounts SET msgs = msgs + 1 WHERE id = ?", a.acc);
      const mr = this.rows("SELECT msgs FROM accounts WHERE id = ?", a.acc)[0]; msgN = mr ? mr.msgs : 0;
    } catch (e) {}
    try { ws.send(JSON.stringify({ type: "msgs", n: msgN })); } catch (e) {}
    this.chatMem.push({ id, ts: now, name, acc: a.acc, adm: adm === 1, text });
    if (this.chatMem.length > CHAT_HIST) this.chatMem.shift();
    this.broadcastJson({ type: "chat", id, ts: now, name, acc: a.acc, av: this.avatarOf(a.acc), adm: adm === 1, text });
  }

  // Bir dünyanın haritasını tamamen boşaltır. Oyuncular bağlı kalır, ekranları temizlenir.
  resetWorld(w) {
    if (!WORLDS[w]) return;
    this.worlds[w].fill(0);
    this.dirty[w].clear();
    if (WORLDS[w].table) this.ctx.storage.sql.exec("DELETE FROM " + WORLDS[w].table);
    const msg = JSON.stringify({ type: "reset", world: w });
    for (const s of this.ctx.getWebSockets()) {
      const a = s.deserializeAttachment() || {};
      if ((WORLDS[a.w] ? a.w : 1) !== w) continue;
      try { s.send(msg); } catch (e) { /* kapanmış bağlantı */ }
    }
  }

  async api(request) {
    if (request.method !== "POST") return jsonRes({ error: "Yanlış istek" }, 405);
    let body;
    try { body = await request.json(); } catch (e) { return jsonRes({ error: "Geçersiz istek" }, 400); }
    if (!body || typeof body !== "object") return jsonRes({ error: "Geçersiz istek" }, 400);
    const ip = request.headers.get("CF-Connecting-IP") || "yerel";
    const path = new URL(request.url).pathname;
    try {
      if (path === "/api/register") return jsonRes(await this.register(body, ip));
      if (path === "/api/login") return jsonRes(await this.login(body, ip));
      if (path === "/api/recover") return jsonRes(await this.recover(body, ip));
      if (path === "/api/logout") return jsonRes(await this.logout(body));
      if (path === "/api/admin") return jsonRes(await this.adminLogin(body, ip));
      if (path === "/api/adminlogout") return jsonRes(await this.adminLogout(body));
      if (path === "/api/avatar") return jsonRes(await this.setAvatar(body));
      return jsonRes({ error: "Bulunamadı" }, 404);
    } catch (e) {
      if (e instanceof ApiError) return jsonRes({ error: e.message }, e.status);
      return jsonRes({ error: "Sunucu hatası" }, 500);
    }
  }

  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === "/durum") {
      const cnt = {};
      for (const w of [1, 2, 3, 4, 5, 6]) { let n = 0; const a = this.worlds[w]; for (let i = 0; i < a.length; i++) if (a[i]) n++; cnt[w] = n; }
      const pend = {}; for (const w of [1, 2, 3, 4, 5, 6]) pend[w] = this.dirty[w].size;
      const inSea = {};
      for (const w of [1, 2, 3, 4, 6]) { const sm = w === 6 ? SEA6 : SEA, a = this.worlds[w]; let n = 0; for (let i = 0; i < a.length; i++) if (a[i] && sm[i]) n++; inSea[w] = n; }
      return new Response(JSON.stringify({
        surum: VERSION, denizKorumasiAcik: this.sea, dunya6SiyahSinirBoyanabilir: this.b6p, dunya6KirmiziSinirBoyanabilir: this.r6p, denizdekiPiksel: inSea, bellekteDoluPiksel: cnt, yazilmayiBekleyenParca: pend,
        sonBasariliKayit: this.saveOkAt ? new Date(this.saveOkAt).toISOString() : null,
        sonHata: this.saveErr || null, sonHataZamani: this.saveErrAt ? new Date(this.saveErrAt).toISOString() : null,
      }, null, 1), { headers: { "content-type": "application/json; charset=utf-8" } });
    }
    if (url.pathname.startsWith("/api/")) return this.api(request);
    const token = url.searchParams.get("token") || "";
    const acc = token ? await this.accountByToken(token) : null;
    // Misafir kimliği "g" ile başlar, hesap kimliği "a" ile: ikisi karışmaz
    const id = acc ? "a" + acc.id : "g" + ((url.searchParams.get("id") || "").slice(0, 40) || crypto.randomUUID());
    if (acc && acc.ban_until > Date.now()) {      // yasaklı hesap: bilgi ver ve kapat
      const bp = new WebSocketPair(); const [bc, bs] = Object.values(bp);
      bs.accept(); bs.send(JSON.stringify({ type: "banned", until: acc.ban_until, text: trTime(acc.ban_until) })); bs.close(4003, "banned");
      return new Response(null, { status: 101, webSocket: bc });
    }
    const atok = url.searchParams.get("atok") || "";
    let admin = false, ah = "";
    if (atok.length === 64) {
      ah = await sha256hex(atok);
      admin = this.rows("SELECT 1 FROM admin_sessions WHERE hash = ?", ah).length > 0;
    }
    const wq = parseInt(url.searchParams.get("w") || "1", 10);
    const w = WORLDS[wq] ? wq : 1;
    const pair = new WebSocketPair();
    const [client, server] = Object.values(pair);
    this.ctx.acceptWebSocket(server);
    const att0 = acc ? { id, acc: acc.id, w, name: acc.name } : { id, w };
    if (admin) { att0.admin = true; att0.ah = ah; }
    server.serializeAttachment(att0);
    if (admin) server.send(JSON.stringify({ type: "admin", ok: true }));
    else if (atok) server.send(JSON.stringify({ type: "badadmin" }));
    if (acc) {
      const now = Date.now();
      const rk = id + "|" + w;
      const saved = this.loadAccRate(acc.id, w);
      let used = Math.max(0, saved.used - (now - saved.ts) / 1000);
      const live = this.rates.get(rk);
      if (live) used = Math.max(0, live.used - (now - live.ts) / 1000);
      else this.rates.set(rk, { used, ts: now });
      if (!this.accCache.has(acc.id)) this.accCache.set(acc.id, { total: acc.total });
      const c = this.accCache.get(acc.id);
      server.send(JSON.stringify({ type: "account", account: { id: acc.id, name: acc.name, total: c.total, used, world: w, avatar: acc.avatar || "", msgs: acc.msgs || 0 } }));
    } else if (token) {
      server.send(JSON.stringify({ type: "badtoken" }));
    }
    server.send(JSON.stringify({ type: "settings", sea: this.sea, b6: this.b6p, r6: this.r6p, ver: VERSION }));
    if (this.ann && Date.now() - this.ann.ts < 600000) server.send(JSON.stringify(this.ann));   // son 10 dk içindeki duyuruyu yeni gelenler de görür
    server.send(JSON.stringify({ type: "colors", list: [...this.ccolors] }));
    server.send(JSON.stringify({ type: "labels", list: this.labelList(w) }));   // özel renkler, harita anlık görüntüsünden ÖNCE gelir
    { const hist = this.chatHistory(); server.send(JSON.stringify({ type: "chathist", msgs: hist, avs: this.chatAvatars(hist) })); }
    this.sendSnapshot(server, w);
    this.broadcastOnline();
    return new Response(null, { status: 101, webSocket: client });
  }

  sendSnapshot(ws, w) {
    const SZ = 40000;
    let buf = new Uint32Array(SZ + 1);
    buf[0] = T_SNAPSHOT;
    let n = 0;
    const world = this.worlds[w];
    const cells = NW[w];
    for (let i = 0; i < cells; i++) {
      const c = world[i];
      if (c === 0) continue;
      buf[++n] = i * 64 + c;
      if (n === SZ) {
        ws.send(buf.buffer);
        buf = new Uint32Array(SZ + 1);
        buf[0] = T_SNAPSHOT;
        n = 0;
      }
    }
    if (n > 0) ws.send(buf.slice(0, n + 1).buffer);
    ws.send(new Uint32Array([T_SNAPSHOT_END]).buffer);
  }

  async webSocketMessage(ws, message) {
    if (typeof message === "string") {
      // "ping" otomatik yanıtlanıyor; buraya yalnızca yönetici komutları gelir
      if (message.charAt(0) !== "{" || message.length > 1000) return;
      let m;
      try { m = JSON.parse(message); } catch (e) { return; }
      const a = ws.deserializeAttachment() || {};
      if (!m) return;
      if (m.type === "chat") { this.handleChat(ws, a, m); return; }   // sohbet: hesabı olan herkes
      if (m.type === "labelset" || m.type === "labelren" || m.type === "labeldel") { this.handleLabel(ws, a, m); return; }
      if (m.type === "newcolor") { this.handleNewColor(ws, a, m); return; }
      if (m.type === "dm") { this.handleDm(ws, a, m); return; }
      if (m.type === "dmhist") { this.dmHist(ws, a, m); return; }
      if (m.type === "dmlist") { this.dmList(ws, a); return; }
      if (!a.admin) return;                                // aşağıdakiler yalnızca yönetici
      if (m.type === "unlimited") ws.serializeAttachment({ ...a, unl: m.on === true });
      else if (m.type === "reset") this.resetWorld(Number(m.world));
      else if (m.type === "sea") {
        this.sea = m.on === true;
        this.ctx.storage.sql.exec("INSERT OR REPLACE INTO settings (k, v) VALUES ('sea', ?)", this.sea ? "1" : "0");
        this.broadcastJson({ type: "settings", sea: this.sea, b6: this.b6p, r6: this.r6p, ver: VERSION });
      } else if (m.type === "b6") {
        this.b6p = m.on === true;
        this.ctx.storage.sql.exec("INSERT OR REPLACE INTO settings (k, v) VALUES ('b6p', ?)", this.b6p ? "1" : "0");
        this.broadcastJson({ type: "settings", sea: this.sea, b6: this.b6p, r6: this.r6p, ver: VERSION });
      } else if (m.type === "r6") {
        this.r6p = m.on === true;
        this.ctx.storage.sql.exec("INSERT OR REPLACE INTO settings (k, v) VALUES ('r6p', ?)", this.r6p ? "1" : "0");
        this.broadcastJson({ type: "settings", sea: this.sea, b6: this.b6p, r6: this.r6p, ver: VERSION });
      } else if (m.type === "announce") {
        if (m.clear === true) { this.ann = null; this.broadcastJson({ type: "announce", clear: true }); return; }
        const text = String(m.text || "").replace(/[\u0000-\u001f\u007f]/g, " ").replace(/\s+/g, " ").trim().slice(0, 120);
        if (!text) return;
        const col = (v, d) => (/^#[0-9a-fA-F]{6}$/.test(String(v)) ? String(v) : d);
        const style = ["normal", "bold", "italic", "bolditalic", "mono"].includes(m.style) ? m.style : "normal";
        const dir = m.dir === "left" ? "left" : "right";
        const speed = ["slow", "normal", "fast"].includes(m.speed) ? m.speed : "normal";
        this.ann = { type: "announce", text, bg: col(m.bg, "#1e88e5"), fg: col(m.fg, "#ffffff"), glow: m.glow === true, style, dir, speed, ts: Date.now() };
        this.broadcastJson(this.ann);
      } else if (m.type === "seaclean") {
        const w = Number(m.world);
        const sm = w === 6 ? SEA6 : ([1, 2, 3, 4].includes(w) ? SEA : null);
        if (!sm) { ws.send(JSON.stringify({ type: "seaclean", world: w, n: -1 })); return; }
        const arr = this.worlds[w]; let n = 0;
        for (let i = 0; i < arr.length; i++) {
          if (arr[i] && sm[i]) { arr[i] = 0; n++; if (WORLDS[w].table) this.dirty[w].add(i >>> 16); }
        }
        if (n > 0 && WORLDS[w].table) await this.ctx.storage.setAlarm(Date.now() + 1500);
        ws.send(JSON.stringify({ type: "seaclean", world: w, n }));
        if (n > 0) for (const x of this.ctx.getWebSockets()) {      // o dünyadakiler yeniden bağlanıp temiz haritayı alır
          const t = x.deserializeAttachment() || {};
          if ((WORLDS[t.w] ? t.w : 1) === w) { try { x.close(1012, "yenile"); } catch (e) {} }
        }
      } else if (m.type === "admlist") {
        const q = String(m.q || "").toLowerCase().replace(/[%_\\]/g, "").slice(0, 16);
        const on = new Set(this.ctx.getWebSockets().map((x) => { const t = x.deserializeAttachment() || {}; return t.acc || 0; }));
        const list = this.rows("SELECT id, name, total, ban_until, mute_until FROM accounts WHERE name_lc LIKE ? ORDER BY id DESC LIMIT 100", "%" + q + "%")
          .map((r) => ({ id: r.id, name: r.name, total: r.total, ban: r.ban_until, mute: r.mute_until, on: on.has(r.id) }));
        ws.send(JSON.stringify({ type: "admlist", list, now: Date.now() }));
      } else if (m.type === "admban" || m.type === "admmute") {
        const id = Number(m.id), mins = Number(m.mins);
        if (!Number.isInteger(id) || !Number.isFinite(mins)) return;
        const now = Date.now();
        const until = mins < 0 ? FOREVER : mins > 0 ? now + Math.min(mins, 525600 * 10) * 60000 : 0;
        const col = m.type === "admban" ? "ban_until" : "mute_until";
        this.ctx.storage.sql.exec("UPDATE accounts SET " + col + " = ? WHERE id = ?", until, id);
        for (const x of this.ctx.getWebSockets()) {
          const t = x.deserializeAttachment() || {};
          if (t.acc !== id) continue;
          try {
            if (col === "ban_until" && until > 0) { x.send(JSON.stringify({ type: "banned", until, text: trTime(until) })); x.close(4003, "banned"); }
            else if (col === "mute_until" && until > 0) x.send(JSON.stringify({ type: "chaterr", msg: "Susturuldun. Süre: " + trTime(until) }));
          } catch (e) {}
        }
        ws.send(JSON.stringify({ type: "admdone" }));
      } else if (m.type === "chatdel") {
        const id = Number(m.id);
        this.ctx.storage.sql.exec("DELETE FROM chat WHERE id = ?", id);
        this.broadcastJson({ type: "chatdel", id });
      }
      return;
    }
    if (message.byteLength === 0 || message.byteLength % 4 !== 0) return;
    if (message.byteLength > MAX_BATCH * 4) return;

    const arr = new Uint32Array(message);
    const att = ws.deserializeAttachment() || {};
    const id = att.id || "gbilinmiyor";
    const w = WORLDS[att.w] ? att.w : 1;      // eski bağlantılarda w yok: Dünya 1
    const unl = !!(att.admin && att.unl) || !!WORLDS[w].free;     // yönetici sınırsız modu
    const cfg = WORLDS[w];
    const world = this.worlds[w];
    const rk = id + "|" + w;
    const now = Date.now();
    let r = this.rates.get(rk);
    if (!r && att.acc) {
      // Sunucu belleği sıfırlandıysa hesabın sayacını veritabanından geri yükle
      const saved = this.loadAccRate(att.acc, w);
      r = { used: Math.max(0, saved.used - (now - saved.ts) / 1000), ts: now };
    }
    if (!r) r = { used: 0, ts: now };
    r.used = Math.max(0, r.used - (now - r.ts) / 1000);
    r.ts = now;

    const accepted = [];
    const rejected = [];
    let seaN = 0, seaRefund = 0, erased = 0, bordN = 0, redN = 0;
    for (let k = 0; k < arr.length; k++) {
      const v = arr[k];
      const idx = v >>> 6;
      const c = v & 63;
      if (idx >= NW[w] || (c < 1 && !(att.admin && c === 0))) continue;   // c = 0: silgi (yalnızca yönetici)
      const cur = world[idx];
      if (c === 0) {                                  // silgi: hücre en baştaki haline (haritanın kendi rengine) döner
        if (cur === 0) continue;
        world[idx] = 0;
        if (cfg.table) this.dirty[w].add(idx >>> 16);
        accepted.push(v); erased++;
        continue;
      }
      if (c === BLOCKED_C || c > 34 && !this.ccolors.has(c)) {      // yasak renk ya da tanımsız özel renk: reddet
        rejected.push(idx * 64 + cur);
        continue;
      }
      const seaMap = w === 6 ? SEA6 : (w === 5 ? null : SEA);
      if (this.sea && seaMap && seaMap[idx] && cur === 0) {      // deniz koruması açıkken BOŞ denize piksel konamaz (denizdeki mevcut pikselin rengi değiştirilebilir)
        rejected.push(idx * 64 + cur);
        seaN++; seaRefund += cur ? cfg.filled : cfg.empty;
        continue;
      }
      if (w === 6 && !this.b6p && BORD6[idx] && cur === 0) {      // Dünya 6: siyah il sınırları kapalıyken BOŞ sınır hücresine basılamaz (boyalı olanlar korunur)
        rejected.push(idx * 64 + cur);
        bordN++;
        continue;
      }
      if (w === 6 && !this.r6p && RED6[idx] && cur === 0) {       // Dünya 6: kırmızı bölge sınırları kapalıyken BOŞ hücreye basılamaz
        rejected.push(idx * 64 + cur);
        redN++;
        continue;
      }
      if (cur === c) continue;
      const cost = cur ? cfg.filled : cfg.empty;   // dolu hücre daha pahalı olabilir
      if (!unl && r.used + cost > cfg.max + SLACK) {
        rejected.push(idx * 64 + cur);
        continue;
      }
      if (!unl) r.used += cost;
      world[idx] = c;
      if (cfg.table) this.dirty[w].add(idx >>> 16);
      accepted.push(v);
    }
    if (!cfg.free) this.rates.set(rk, r);
    if (att.acc && !cfg.free) {                      // Dünya 4 hesabın toplamına sayılmaz
      let c = this.accCache.get(att.acc);
      if (!c) {
        const row = this.rows("SELECT total FROM accounts WHERE id = ?", att.acc)[0];
        c = { total: row ? row.total : 0 };
        this.accCache.set(att.acc, c);
      }
      c.total += accepted.length - erased;           // silinen hücreler toplama eklenmez
      this.accDirty.add(att.acc + "|" + w);
    }

    if (rejected.length) ws.send(new Uint32Array([T_REJECT, ...rejected]).buffer);
    if (redN) ws.send(JSON.stringify({ type: "sea", n: 0, refund: 0, text: "Kırmızı sınırlar boyanamaz" }));
    if (bordN) ws.send(JSON.stringify({ type: "sea", n: 0, refund: 0, text: "Siyah sınırlar boyanamaz" }));
    if (seaN) ws.send(JSON.stringify({ type: "sea", n: seaN, refund: (unl || cfg.free) ? 0 : seaRefund }));
    if (accepted.length) {
      this.lastPixelAt = now;
      const out = new Uint32Array([T_PIXELS, ...accepted]).buffer;
      for (const other of this.ctx.getWebSockets()) {
        if (other === ws) continue;
        const oa = other.deserializeAttachment() || {};
        if ((WORLDS[oa.w] ? oa.w : 1) !== w) continue;   // yalnızca aynı dünyadakilere
        try { other.send(out); } catch (e) { /* kapanmış bağlantı */ }
      }
      if (cfg.table && (await this.ctx.storage.getAlarm()) === null) {
        await this.ctx.storage.setAlarm(Date.now() + FLUSH_MS);
      }
    }
  }

  async alarm() {
    let saveFailed = false;
    for (const w of [1, 2, 3, 4, 5, 6]) {
      if (!WORLDS[w].table) continue;
      for (const id of [...this.dirty[w]]) {
        try {
          const start = id * CHUNK;
          const end = Math.min(NW[w], start + CHUNK);
          this.ctx.storage.sql.exec(
            "INSERT OR REPLACE INTO " + WORLDS[w].table + " (id, data) VALUES (?, ?)",
            id,
            this.worlds[w].slice(start, end).buffer
          );
          this.dirty[w].delete(id);      // yalnızca başarıyla yazılan parça "bekleyen" listesinden çıkar
          this.saveOkAt = Date.now();
        } catch (e) {
          saveFailed = true;             // yazılamadı: parça listede kalır, biraz sonra tekrar denenir
          this.saveErr = String((e && e.message) || e).slice(0, 300);
          this.saveErrAt = Date.now();
        }
      }
    }
    const t = Date.now();
    const idle = t - this.lastPixelAt >= FLUSH_MS;     // durduysa hemen yaz (bellek boşalmadan)
    if (this.accDirty.size && (idle || t - this.lastAccFlush >= ACC_FLUSH_MS)) {
      for (const key of this.accDirty) {
        const [a, wStr] = key.split("|");
        const accId = Number(a), w = Number(wStr);
        const c = this.accCache.get(accId);
        const r = this.rates.get("a" + accId + "|" + w);
        if (!c) continue;
        const used = r ? r.used : 0, ts = r ? r.ts : Date.now();
        if (w === 1) {
          this.ctx.storage.sql.exec("UPDATE accounts SET total = ?, used = ?, ts = ? WHERE id = ?", c.total, used, ts, accId);
        } else {
          this.ctx.storage.sql.exec("UPDATE accounts SET total = ? WHERE id = ?", c.total, accId);
          this.ctx.storage.sql.exec(
            "INSERT OR REPLACE INTO acc_rates (acc, w, used, ts) VALUES (?, ?, ?, ?)", accId, w, used, ts
          );
        }
      }
      this.accDirty.clear();
      this.lastAccFlush = t;
    }
    const cutoff = Date.now() - 5 * 60 * 1000;
    for (const [k, v] of this.rates) if (v.ts < cutoff) this.rates.delete(k);
    if (saveFailed) await this.ctx.storage.setAlarm(Date.now() + 20000);              // harita yazılamadı: 20 sn sonra tekrar dene
    else if (this.accDirty.size) await this.ctx.storage.setAlarm(Date.now() + FLUSH_MS);   // bekleyen hesap yazımı için tekrar uyan
  }

  async webSocketClose(ws, code) {
    try { ws.close(code === 1005 ? 1000 : code, "kapandı"); } catch (e) { /* zaten kapalı */ }
    if (Object.values(this.dirty).some((d) => d.size > 0)) { try { await this.alarm(); } catch (e) {} }   // bekleyen pikseller kaybolmasın
    this.broadcastOnline(ws);
  }

  async webSocketError(ws) {
    try { ws.close(1011, "hata"); } catch (e) { /* zaten kapalı */ }
    this.broadcastOnline(ws);
  }

  broadcastOnline(except) {
    const live = this.ctx.getWebSockets().filter((s) => s !== except && s.readyState === 1);
    const groups = { 1: [], 2: [], 3: [], 4: [], 5: [], 6: [] };
    for (const s of live) {
      const a = s.deserializeAttachment() || {};
      groups[WORLDS[a.w] ? a.w : 1].push(s);
    }
    for (const w of [1, 2, 3, 4, 5, 6]) {
      const msg = new Uint32Array([T_ONLINE, groups[w].length]).buffer;
      for (const s of groups[w]) {
        try { s.send(msg); } catch (e) { /* kapanmış bağlantı */ }
      }
    }
  }
}
